function b64ToUtf8(b64) {
  const binStr = atob(b64);
  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) {
    bytes[i] = binStr.charCodeAt(i);
  }
  return new TextDecoder("utf-8").decode(bytes);
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    
    if (url.pathname === "/manifest.json") {
      return new Response(`{"name":"HARZ Browser","short_name":"Browser","description":"Fast, Private browser for the HARZ Ecosystem","start_url":"/","display":"standalone","background_color":"#f0f2f5","theme_color":"#f0f2f5","orientation":"portrait","icons":[{"src":"/icon.svg","sizes":"any","type":"image/svg+xml","purpose":"any maskable"}]}`, {
        headers: { "Content-Type": "application/manifest+json", "Cache-Control": "public, max-age=3600" }
      });
    }
    if (url.pathname === "/sw.js") {
      return new Response(b64ToUtf8(""), {
        headers: { "Content-Type": "application/javascript", "Cache-Control": "no-cache, must-revalidate" }
      });
    }
    if (url.pathname === "/icon.svg" || url.pathname === "/icon.png") {
      return new Response(`<svg xmlns="http://www.w3.org/2000/svg" width="192" height="192" viewBox="0 0 192 192"><rect width="192" height="192" rx="40" fill="#f0f2f5"/><circle cx="96" cy="96" r="50" fill="none" stroke="#1877f2" stroke-width="6"/><path d="M46 96h100M96 46v100M60 60c20 20 20 52 0 72M132 60c-20 20-20 52 0 72" stroke="#1877f2" stroke-width="4" fill="none"/></svg>`, {
        headers: { "Content-Type": "image/svg+xml", "Cache-Control": "public, max-age=86400" }
      });
    }

    if (url.pathname === "/page") {
      const target = url.searchParams.get("url") || "";
      if (!/^https?:\/\//i.test(target)) return new Response("bad url", { status: 400 });
      let r;
      try {
        r = await fetch(target, {
          headers: {
            "User-Agent": "Mozilla/5.0 (Linux; Android 10; Infinix XOS) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36",
            "Accept": "text/html,application/xhtml+xml,*/*"
          },
          redirect: "follow"
        });
      } catch (err) {
        return new Response("upstream fetch failed", { status: 502 });
      }
      const finalUrl = r.url || target;
      const ct = r.headers.get("content-type") || "";
      if (!ct.includes("html")) {
        return new Response(r.body, { status: r.status, headers: {
          "Content-Type": ct || "application/octet-stream",
          "Content-Security-Policy": "sandbox",
          "Cache-Control": "no-store"
        } });
      }
      let body = await r.text();
      const jsUrl = finalUrl.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
      const inj = '<base href="' + finalUrl.replace(/"/g, "&quot;") + '">' +
        '<script>document.addEventListener("click",function(e){var t=e.target;var a=t&&t.closest?t.closest("a[href]"):null;if(a){e.preventDefault();parent.postMessage({harzNav:a.href},"*");}},true);' +
        'setTimeout(function(){try{parent.postMessage({harzTitle:document.title,harzUrl:"' + jsUrl + '"},"*");}catch(e){}},300);<' + '/script>';
      if (/<head[^>]*>/i.test(body)) {
        body = body.replace(/<head[^>]*>/i, m => m + inj);
      } else {
        body = inj + body;
      }
      return new Response(body, { status: r.ok ? 200 : 502, headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Content-Security-Policy": "sandbox allow-scripts allow-forms allow-popups",
        "X-Content-Type-Options": "nosniff",
        "Cache-Control": "no-store"
      } });
    }

    const html = b64ToUtf8("");

    return new Response(html, {
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "no-cache, must-revalidate",
        "Access-Control-Allow-Origin": "*"
      }
    });
  }
};
